// ================== CẤU HÌNH ==================
const CONFIG = {
  WEBHOOK_SECRET: 'doi-chuoi-bi-mat-nay',              // khớp ?secret=... trong URL webhook bên Crisp
  JIRA_BASE_URL: 'https://your-company.atlassian.net',
  SUPABASE_URL: 'https://xxxxxxxx.supabase.co',
  TIMEZONE: 'Asia/Ho_Chi_Minh',
  ACCEPT_TEXT_MESSAGES: false,   // true = nhận cả link CS dán trong tin nhắn thường, không chỉ note
  IGNORE_COMMENT_AUTHORS: ['Automation for Jira'],
};
// ==============================================
const item = $input.first().json;
const body = item.body || {};
if (CONFIG.WEBHOOK_SECRET && (item.query || {}).secret !== CONFIG.WEBHOOK_SECRET) return [];

const data = body.data || {};
if (data.from !== 'operator') return [];
if (!(data.type === 'note' || (CONFIG.ACCEPT_TEXT_MESSAGES && data.type === 'text'))) return [];
const content = typeof data.content === 'string' ? data.content : '';
if (/^(🔔|🔗|🤖|⚠️)/u.test(content.trim())) return [];   // note do hệ thống tạo -> bỏ qua

const host = CONFIG.JIRA_BASE_URL.replace(/^https?:\/\//, '').replace(/\/+$/, '').replace(/\./g, '\\.');
const keys = new Set();
for (const m of content.matchAll(new RegExp(host + '\\/browse\\/([A-Z][A-Z0-9_]+-\\d+)', 'g'))) keys.add(m[1]);
for (const m of content.matchAll(new RegExp(host + '\\/[^\\s]*[?&]selectedIssue=([A-Z][A-Z0-9_]+-\\d+)', 'g'))) keys.add(m[1]);
if (!keys.size) return [];

const websiteId = data.website_id || body.website_id;
return [...keys].map(k => ({ json: {
  config: CONFIG,
  website_id: websiteId,
  session_id: data.session_id,
  issue_key: k,
  linked_by: data.user?.user_id || '',
  linked_by_name: data.user?.nickname || '',
} }));

function adfToText(n) {
  if (!n) return '';
  if (typeof n === 'string') return n;
  if (n.type === 'text') return n.text || '';
  if (n.type === 'hardBreak') return '\n';
  if (n.type === 'mention') return n.attrs?.text || '';
  if (n.type === 'media' || n.type === 'mediaInline') return `[Ảnh: ${n.attrs?.alt || 'không tên'}]`;
  if (n.type === 'inlineCard' || n.type === 'blockCard') return n.attrs?.url || '';
  const inner = (n.content || []).map(adfToText).join('');
  if (n.type === 'listItem') return '• ' + inner;
  return ['paragraph', 'heading', 'blockquote', 'codeBlock'].includes(n.type) ? inner + '\n' : inner;
}
function fmt(t, tz) {
  const d = typeof t === 'number' ? new Date(t) : new Date(t || Date.now());
  if (isNaN(d)) return '?';
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: tz, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
    .formatToParts(d).map(x => [x.type, x.value]));
  return `${p.day}/${p.month}/${p.year} ${p.hour}:${p.minute}`;
}
const norm = v => String(v || '').toLowerCase();
const matchAny = (name, list) => (list || []).some(x => x && norm(name).includes(norm(x)));
const marker = (key, status, at) => `[jira-sync ${key} | status=${status} | at=${at}]`;

const ex = $('Extract Jira Links').all().map(x => x.json);
const issues = $('Get Issue').all().map(x => x.json);
const comments = $input.all().map(x => x.json);
const cfg = ex[0].config;
const nowIso = new Date().toISOString();

return ex.map((e, i) => {
  const iss = issues[i] || {};
  const url = `${cfg.JIRA_BASE_URL}/browse/${e.issue_key}`;
  if (!iss.fields) {
    return { json: { ...e, active: false, last_status: null, last_seen_at: nowIso,
      note: `⚠️ Không tìm thấy ticket ${e.issue_key} trên Jira (sai mã hoặc tài khoản API không có quyền xem). Hệ thống sẽ không theo dõi ticket này.\n${url}` } };
  }
  const f = iss.fields;
  const cms = (comments[i]?.comments || []).filter(c => !matchAny(c.author?.displayName, cfg.IGNORE_COMMENT_AUTHORS));
  const latest = cms[0];   // orderBy=-created -> phần tử đầu là mới nhất
  const status = f.status?.name || '?';
  const baselineAt = latest?.created || nowIso;
  const lastUpdate = latest
    ? `${fmt(latest.created, cfg.TIMEZONE)} (${latest.author?.displayName || '?'}: "${adfToText(latest.body).trim().replace(/\s+/g, ' ').slice(0, 120)}")`
    : `${fmt(f.updated, cfg.TIMEZONE)} (chưa có comment)`;
  const note = [
    `🔗 ĐÃ THEO DÕI JIRA · ${e.issue_key}`,
    f.summary || '',
    url,
    `Trạng thái hiện tại: ${status}`,
    `Cập nhật mới nhất: ${lastUpdate}`,
    `Từ giờ hệ thống tự thêm ghi chú khi ticket có comment mới hoặc đổi trạng thái.`,
    marker(e.issue_key, status, baselineAt),
  ].join('\n');
  return { json: { ...e, active: true, last_status: status, last_seen_at: baselineAt, note } };
});

const ex = $('Build Confirm Note').all().map(x => x.json);
const meta = ($input.first().json || {}).data || {};
const current = meta.data && typeof meta.data === 'object' ? meta.data : {};
const keys = new Set(String(current.jira_keys || '').split(/[\s,;]+/).filter(Boolean));
ex.filter(e => e.active).forEach(e => keys.add(e.issue_key));
return [{ json: { website_id: ex[0].website_id, session_id: ex[0].session_id, data: { ...current, jira_keys: [...keys].join(',') } } }];
